// --- TYPES ---
interface CNCondition {
  id: string
  mode: 'pose' | 'depth' | 'canny'
  scale: number
  mirror: boolean
  imgB64: string
  preview: string
}

interface UserData {
  id: number
  email: string
  ticketBalance: number
  avatarUrl?: string | null
}

interface ImageItem {
  id: number
  imageUrl: string
  thumbnailUrl?: string | null
  prompt: string
  model: string
  createdAt?: string
  referenceImageUrls?: string[]
  failed?: boolean
  failError?: string
  // Failed-tile identity: server GenerationQueue row id + a stable key used to
  // dedupe an optimistic local fail against its server row ("qf-<rowId>" or
  // "rf-<falRequestId>"). Fails are per-account and persist until dismissed.
  queueRowId?: number
  failKey?: string
  aspectRatio?: string
  quality?: string
  videoMetadata?: Record<string, any>
  loraUrl?: string | null
  loraName?: string | null
  r2Key?: string
}

// Reve, Grok and Meta Muse accept ratios the earlier models never offered
type AspectRatio = "auto" | "1:1" | "2:3" | "3:2" | "4:5" | "5:4" | "3:4" | "4:3" | "9:16" | "16:9" | "21:9"
  | "2:1" | "1:2" | "9:21"
  | "1024x768" | "1024x1024" | "1024x1536" | "1920x1080" | "2560x1440" | "3840x2160"
type Quality = "1k" | "2k" | "3k" | "4k" | "low" | "medium" | "high"

// --- IMAGE MODEL CONFIG ---
interface ImageModelConfig {
  id: string       // internal ID used by our UI
  apiId: string    // ID sent to /api/generate
  name: string
  aspectRatios: AspectRatio[]
  supportsQuality: boolean
  qualityOptions?: Quality[]       // custom quality options (defaults to ["2k","4k"])
  maxReferenceImages: number
  requiresReferenceImage?: boolean // if true, at least 1 ref image required
  supportsOutputFormat?: boolean   // shows png/jpeg/webp picker
  isFal: boolean   // true = async FAL queue; false = sync Gemini
  maxImages?: number               // if > 1, shows image count picker
  isUpscaler?: boolean             // special upscaler UI — takes image URL + params instead of prompt
  isTryOn?: boolean                // Virtual Try-On: two named images (person + garment), no prompt
  isLocalModel?: boolean           // admin-only: runs on local GPU via upscaler-server.py
  isCustomFlux?: boolean           // admin-only: custom Flux checkpoint + LoRA inference
  supportsSafetyChecker?: boolean  // fal content-safety toggle: admins can flip it (default off), non-admins are forced ON (CCBill)
}

