// --- HELPERS ---
function calcTicketCost(modelId: string, quality: Quality, aspectRatio?: AspectRatio, loraActive?: boolean, hasRefImages?: boolean): number {
  if (modelId === "nano-banana-pro")     return quality === "4k" ? 14 : 7
  if (modelId === "nano-banana-pro-2")   return quality === "4k" ? 12 : 7
  if (modelId === "seedream-4.5")        return quality === "4k" ? 4 : 2
  if (modelId === "seedream-5-lite")     return quality === "3k" ? 4 : 2
  if (modelId === "seedream-5-pro")      return 10   // flat 10 tickets/generation
  if (modelId === "recraft-v4.1")        return 15   // flat 15 tickets/generation
  if (modelId === "flux-1-dev") {
    if (hasRefImages) return quality === "4k" ? 8 : quality === "2k" ? 6 : 3  // i2i
    return quality === "4k" ? 6 : quality === "2k" ? 5 : 2                    // t2i
  }
  if (modelId === "flux-2") {
    if (loraActive && hasRefImages) return 3  // i2i+LoRA (1024×1024 tier)
    if (loraActive) return 2                  // t2i+LoRA (0-2 GB tier)
    return 1
  }
  if (modelId === "z-image-base")        return quality === "4k" ? 15 : quality === "2k" ? 4 : 1
  if (modelId === "z-image-turbo")       return loraActive ? (quality === "4k" ? 17 : quality === "2k" ? 5 : 1) : (quality === "4k" ? 8 : quality === "2k" ? 2 : 1)
  if (modelId === "clarity-upscaler")    return 7 // base; upscaler uses upscaleFactor-dependent cost computed separately
  if (modelId === "aura-sr")             return 1
  if (modelId === "esrgan")              return 1
  if (modelId === "drct")               return 1 // minimum; actual cost computed server-side from output MP
  if (modelId === "supir")              return 8
  if (modelId === "google-virtual-try-on") return 2   // matches ai-models.config.ts
  if (modelId === "kling-v3-image")     return 2
  if (modelId === "kling-o3-image")     return quality === "4k" ? 4 : 2
  if (modelId === "wan-2.7-pro")        return 4
  if (modelId === "wan-2.2-t2i-lora")   return 2
  if (modelId === "pro-scanner-v3")     return quality === "4k" ? 15 : 7
  if (modelId === "flash-scanner-v2.5") return 1
  if (modelId === "gpt-image-2") {
    if (quality === "low") return 1
    if (quality === "medium") {
      if (aspectRatio === "1024x1024" || aspectRatio === "2560x1440") return 3
      if (aspectRatio === "3840x2160") return 4
      return 2  // 1024x768, 1024x1536, 1920x1080
    }
    if (quality === "high") {
      if (aspectRatio === "1024x1024") return 8
      if (aspectRatio === "2560x1440") return 9
      if (aspectRatio === "3840x2160") return 15
      return 6  // 1024x768, 1024x1536, 1920x1080
    }
    return 1
  }
  // Anything not special-cased above bills straight from the shared config —
  // the same function /api/generate charges with.
  return configTicketCost(modelId, quality)
}

// Human-readable aspect ratio label for pixel-dimension tokens (e.g. "1920x1080" → "16:9")
const PIXEL_DIM_RATIO: Record<string, string> = {
  "1024x1024": "1:1",
  "1024x768":  "4:3",
  "1024x1536": "2:3",
  "1920x1080": "16:9",
  "2560x1440": "16:9",
  "3840x2160": "16:9",
}

// SeeDream 5.0 Lite: combines quality + aspect ratio into image_size params.
// Returns fields to spread directly into the API request body.
function seedream5LiteImageSize(quality: Quality, aspectRatio: AspectRatio): Record<string, string | number> {
  const base = quality === "3k" ? 3072 : 2048
  if (aspectRatio === "1:1") {
    return { image_size: quality === "3k" ? "auto_3K" : "auto_2K" }
  }
  const [wStr, hStr] = aspectRatio.split(":")
  const wRatio = parseInt(wStr)
  const hRatio = parseInt(hStr)
  let width: number, height: number
  if (wRatio >= hRatio) { // landscape
    width = base
    height = Math.round((base * hRatio) / wRatio)
  } else { // portrait
    height = base
    width = Math.round((base * wRatio) / hRatio)
  }
  return { image_size: "custom", custom_width: width, custom_height: height }
}

function getModelDisplayName(apiId: string): string {
  return IMAGE_MODEL_CONFIGS.find((m) => m.apiId === apiId)?.name ?? apiId
}

// --- PROMPT TABS ---
// A tab captures the prompt-box configuration only. Reference images, LoRA
// selection, and upscaler params stay global (not per-tab) by design.
/**
 * Per-model batch caps are a product decision for paying tiers; the owner is
 * spending their own fal credit, so admin accounts get a much higher ceiling
 * on every model rather than the model's advertised 4.
 */
const ADMIN_MAX_IMAGES = 20

interface PromptTab {
  id: string
  name?: string          // user-set label; falls back to the model display name
  modelId: string
  prompt: string
  aspectRatio: string    // validated against the model when APPLIED, not when stored
  quality: string
  outputFormat: "png" | "jpeg" | "webp"
  imageCount: number
  seedreamSafetyChecker?: boolean
  wanSafetyChecker?: boolean
  fluxDevSafetyChecker?: boolean
}
interface PromptTabsState {
  version: 1
  tabs: PromptTab[]
  activeTabId: string
  pinnedTabId: string | null
  updatedAt: number      // reconciliation key: local vs server, newer wins
}
const MAX_PROMPT_TABS = 6
const PROMPT_TABS_LS_KEY = "pv2-prompt-tabs"
const MAX_TAB_PROMPT_LEN = 5000 // keeps the whole blob well under fetch-keepalive's 64KB body cap

function newTabId(): string {
  try { return crypto.randomUUID() } catch { return `tab-${Date.now()}-${Math.random().toString(36).slice(2, 8)}` }
}

// Upscaler/local/custom-flux models can't be pinned for Quick Generate
function isPinnableModelId(modelId: string): boolean {
  const cfg = IMAGE_MODEL_CONFIGS.find(m => m.id === modelId)
  return !!cfg && !cfg.isUpscaler && !cfg.isLocalModel && !cfg.isCustomFlux
}

function defaultPromptTab(model: ImageModelConfig): PromptTab {
  return {
    id: newTabId(),
    modelId: model.isCustomFlux ? "nano-banana-pro-2" : model.id,
    prompt: "",
    aspectRatio: model.aspectRatios[0],
    quality: "2k",
    outputFormat: "png",
    imageCount: 1,
  }
}

function sanitizePromptTabsState(raw: unknown): PromptTabsState | null {
  if (!raw || typeof raw !== "object") return null
  const r = raw as Record<string, unknown>
  if (!Array.isArray(r.tabs)) return null
  const tabs: PromptTab[] = []
  for (const t of r.tabs as unknown[]) {
    if (tabs.length >= MAX_PROMPT_TABS) break
    if (!t || typeof t !== "object") continue
    const o = t as Record<string, unknown>
    if (typeof o.id !== "string" || !o.id) continue
    const cfg = IMAGE_MODEL_CONFIGS.find(m => m.id === o.modelId && !m.isCustomFlux)
    tabs.push({
      id: o.id,
      name: typeof o.name === "string" && o.name.trim() ? o.name.trim().slice(0, 20) : undefined,
      modelId: cfg ? cfg.id : "nano-banana-pro-2",
      prompt: typeof o.prompt === "string" ? o.prompt.slice(0, MAX_TAB_PROMPT_LEN) : "",
      aspectRatio: typeof o.aspectRatio === "string" ? o.aspectRatio : "1:1",
      quality: typeof o.quality === "string" ? o.quality : "2k",
      outputFormat: o.outputFormat === "jpeg" || o.outputFormat === "webp" ? o.outputFormat : "png",
      imageCount: Math.min(Math.max(1, Number(o.imageCount) || 1), ADMIN_MAX_IMAGES),
      seedreamSafetyChecker: o.seedreamSafetyChecker === true || undefined,
      wanSafetyChecker: o.wanSafetyChecker === true || undefined,
      fluxDevSafetyChecker: o.fluxDevSafetyChecker === true || undefined,
    })
  }
  if (tabs.length === 0) return null
  const activeTabId = tabs.some(t => t.id === r.activeTabId) ? (r.activeTabId as string) : tabs[0].id
  // Pin defaults to ON: when no valid pin is stored, pin the active tab
  // (or the first pinnable one) so Quick Generate is discoverable out of the box.
  let pinnedTabId = tabs.some(t => t.id === r.pinnedTabId) ? (r.pinnedTabId as string) : null
  if (!pinnedTabId) {
    const activeTab = tabs.find(t => t.id === activeTabId)
    pinnedTabId = activeTab && isPinnableModelId(activeTab.modelId)
      ? activeTab.id
      : tabs.find(t => isPinnableModelId(t.modelId))?.id ?? null
  }
  return { version: 1, tabs, activeTabId, pinnedTabId, updatedAt: Number(r.updatedAt) || 0 }
}

function copyToClipboard(text: string): Promise<void> {
  if (navigator.clipboard?.writeText) {
    return navigator.clipboard.writeText(text)
  }
  // iOS Safari fallback
  return new Promise((resolve, reject) => {
    const ta = document.createElement("textarea")
    ta.value = text
    ta.style.cssText = "position:fixed;top:0;left:0;opacity:0"
    document.body.appendChild(ta)
    ta.focus()
    ta.select()
    try {
      document.execCommand("copy") ? resolve() : reject(new Error("execCommand failed"))
    } catch (e) { reject(e) }
    finally { document.body.removeChild(ta) }
  })
}

function fileToBase64(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader()
    reader.onload = () => resolve(reader.result as string)
    reader.onerror = reject
    reader.readAsDataURL(file)
  })
}

// Compress a File to a persistent data URL (survives page refresh, storable in localStorage)
async function compressFileToDataUrl(file: File, maxSize = 800, quality = 0.72): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader()
    reader.onload = (ev) => {
      const img = new window.Image()
      img.onload = () => {
        let w = img.width, h = img.height
        if (w > maxSize || h > maxSize) {
          if (w > h) { h = (h / w) * maxSize; w = maxSize } else { w = (w / h) * maxSize; h = maxSize }
        }
        const canvas = document.createElement("canvas")
        canvas.width = w; canvas.height = h
        const ctx = canvas.getContext("2d")
        if (!ctx) { reject(new Error("Canvas unavailable")); return }
        ctx.drawImage(img, 0, 0, w, h)
        const result = canvas.toDataURL("image/jpeg", quality)
        // Release image src and canvas to help mobile browsers free memory sooner
        img.src = ""
        canvas.width = 0; canvas.height = 0
        resolve(result)
      }
      img.onerror = () => reject(new Error("Failed to load image"))
      img.src = ev.target?.result as string
    }
    reader.onerror = () => reject(new Error("Failed to read file"))
    reader.readAsDataURL(file)
  })
}

async function compressBlobToDataUrl(blob: Blob, maxSize = 1920, quality = 0.85): Promise<string> {
  const dataUrl = await new Promise<string>((resolve, reject) => {
    const reader = new FileReader()
    reader.onload = () => resolve(reader.result as string)
    reader.onerror = reject
    reader.readAsDataURL(blob)
  })
  return new Promise((resolve, reject) => {
    const img = new window.Image()
    img.onload = () => {
      let w = img.width, h = img.height
      if (w > maxSize || h > maxSize) {
        if (w > h) { h = (h / w) * maxSize; w = maxSize } else { w = (w / h) * maxSize; h = maxSize }
      }
      const canvas = document.createElement("canvas")
      canvas.width = w; canvas.height = h
      canvas.getContext("2d")?.drawImage(img, 0, 0, w, h)
      resolve(canvas.toDataURL("image/jpeg", quality))
    }
    img.onerror = () => reject(new Error("Failed to load image"))
    img.src = dataUrl
  })
}

// Calculate optimal Flux base dimensions from a reference image's natural size.
// Targets ~1MP total (1024×1024 = Flux sweet spot), snapped to multiples of 64.
function calcImg2ImgDims(nw: number, nh: number): { w: number; h: number } {
  const ratio = nw / nh
  let h = Math.round(Math.sqrt(1024 * 1024 / ratio) / 64) * 64
  let w = Math.round(h * ratio / 64) * 64
  w = Math.max(512, Math.min(2048, w))
  h = Math.max(512, Math.min(2048, h))
  return { w, h }
}

async function refImageToBase64(img: RefImage): Promise<string> {
  if (img.file) return compressFileToDataUrl(img.file, 1920, 0.85)
  // Data URLs are already base64 — no network fetch needed
  if (img.url.startsWith("data:")) return img.url
  // Route through our proxy to avoid CORS issues on Safari when fetching cross-origin R2 URLs
  const proxyUrl = `/api/proxy-image?url=${encodeURIComponent(img.url)}`
  const res = await fetch(proxyUrl)
  if (!res.ok) throw new Error(`Failed to load reference image (${res.status})`)
  const blob = await res.blob()
  return compressBlobToDataUrl(blob, 1920, 0.85)
}

// --- ACCOUNT REFERENCE LIBRARY HELPERS ---
// Compress a File to a JPEG Blob at generation-input quality (1920px/0.85 —
// same as the preset pipeline; the old 800px library path degraded gen inputs).
async function compressFileToBlob(file: File, maxSize = 1920, quality = 0.85): Promise<Blob> {
  const dataUrl = await new Promise<string>((resolve, reject) => {
    const reader = new FileReader()
    reader.onload = () => resolve(reader.result as string)
    reader.onerror = () => reject(new Error("Failed to read file"))
    reader.readAsDataURL(file)
  })
  return new Promise((resolve, reject) => {
    const img = new window.Image()
    img.onload = () => {
      let w = img.width, h = img.height
      if (w > maxSize || h > maxSize) {
        if (w > h) { h = (h / w) * maxSize; w = maxSize } else { w = (w / h) * maxSize; h = maxSize }
      }
      const canvas = document.createElement("canvas")
      canvas.width = w; canvas.height = h
      const ctx = canvas.getContext("2d")
      if (!ctx) { reject(new Error("Canvas unavailable")); return }
      ctx.drawImage(img, 0, 0, w, h)
      canvas.toBlob(
        (blob) => { img.src = ""; canvas.width = 0; canvas.height = 0; blob ? resolve(blob) : reject(new Error("Compression failed")) },
        "image/jpeg",
        quality
      )
    }
    img.onerror = () => reject(new Error("Failed to load image"))
    img.src = dataUrl
  })
}

// Library uploads preserve FULL original quality: web-native formats within the
// upload cap go to R2 byte-for-byte untouched. Only exotic formats (HEIC, TIFF…)
// or oversized files are re-encoded — and then at 4096px/q0.92, not the old
// 1920px/q0.85 (which permanently degraded every stored ref).
async function prepareRefUpload(file: File): Promise<Blob> {
  const webNative = ["image/jpeg", "image/png", "image/webp"].includes(file.type)
  if (webNative && file.size <= 10 * 1024 * 1024) return file
  return compressFileToBlob(file, 4096, 0.92)
}

// Upload a ref blob to R2 via the session-authed upload endpoint → permanent URL
async function uploadRefBlob(blob: Blob): Promise<string> {
  const type = blob.type === "image/png" ? "image/png" : blob.type === "image/webp" ? "image/webp" : "image/jpeg"
  const ext = type === "image/png" ? "png" : type === "image/webp" ? "webp" : "jpg"
  const fd = new FormData()
  fd.append("file", new File([blob], `reference.${ext}`, { type }))
  const res = await fetch("/api/upload-reference", { method: "POST", body: fd })
  if (!res.ok) throw new Error(`Upload failed (${res.status})`)
  const data = await res.json()
  if (!data?.url) throw new Error("Upload returned no URL")
  return data.url as string
}

// Run tasks with bounded concurrency (bulk ref uploads: 100+ files, 4 at a time)
async function runWithConcurrency<T, R>(items: T[], limit: number, worker: (item: T, index: number) => Promise<R>): Promise<PromiseSettledResult<R>[]> {
  const results: PromiseSettledResult<R>[] = new Array(items.length)
  let next = 0
  const lanes = Array.from({ length: Math.min(limit, items.length) }, async () => {
    while (next < items.length) {
      const i = next++
      try {
        results[i] = { status: "fulfilled", value: await worker(items[i], i) }
      } catch (reason) {
        results[i] = { status: "rejected", reason }
      }
    }
  })
  await Promise.all(lanes)
  return results
}

interface RefFolder { id: number; name: string; parentId: number | null }

// --- PENDING SLOT ---
interface PendingSlot {
  slotId: string
  // "done" keeps the card ALIVE after the image arrives. Previously the slot
  // was destroyed and the image re-added as a different element with a
  // different React key, so the tile unmounted/remounted (visible flicker)
  // and jumped to wherever the new element sorted. One generation = one card,
  // from queued through finished/failed, in one fixed position.
  status: "loading" | "failed" | "done"
  prompt: string
  error?: string
  doneImage?: ImageItem  // set with status "done" — rendered in place
  // id of the savedFails entry this slot produced, so the feed can suppress
  // that duplicate while the slot's own error card is still on screen
  failItemId?: number
  // When the user QUEUED this generation. The feed's single ordering key:
  // finished images and error tiles inherit this time (not completion/failure
  // time), so the feed stays in queue order live AND after a refresh.
  queuedAtMs?: number
  queueId?: number       // FAL queue job ID — stored so polling can resume after a page refresh
  queueJobId?: number    // GenerationQueue DB ID — set when the job was queued (capacity exceeded)
  nb2RequestId?: string  // FAL queue request ID for any async image model (NB2, Kling V3/O3, etc.)
  nb2FalEndpoint?: string
  nb2OutputFormat?: string
  nb2AspectRatio?: string
  nb2StatusUrl?: string  // Which status route to poll — defaults to /api/admin/nb2-status
  nb2Quality?: string    // Quality value passed through to the status route (e.g. for Kling O3 ticket cost)
  nb2TicketCost?: number // Per-slot ticket cost, used to refund on failure
  streamDataUrl?: string // Partial or final image URL from SSE streaming (gpt-image-2)
  // Config stored at creation time so failed tiles can show full details in the modal
  modelId?: string
  aspectRatio?: string
  quality?: string
  referenceImageUrls?: string[]
  // Fresh RunPod worker detected for this job (model load ahead → longer ETA)
  coldStart?: boolean
  // RunPod queue tracking: inQueue while no worker has picked the job up;
  // execStartMs = when execution actually began. Timers/ETAs/duration history
  // run from execStartMs so queue wait doesn't pollute them.
  inQueue?: boolean
  execStartMs?: number
  // Full generation settings (flux* keys for custom-flux) — persisted on the
  // slot so a page refresh mid-run doesn't lose them before the DB save
  videoMetadata?: Record<string, unknown>
}

// --- VIDEO TYPES ---
interface VideoModelConfig {
  id: string
  name: string
  durations: string[]
  aspectRatios?: string[]          // Kling / SeeDance
  resolutions?: string[]           // Wan / SeeDance
  supportsEndFrame: boolean
  supportsMotionControl?: boolean  // Motion Control only
  characterOrientations?: string[] // Motion Control only
  audioType: "toggle" | "upload" | "none"
  textToVideo?: boolean            // image is optional (supports text-to-video)
  supportsReferenceVideo?: boolean // SeeDance 2.0 r2v — accepts image_urls[], video_urls[], audio_urls[]
  supportsSD20Modes?: boolean      // SeeDance 2.0 — shows T2V/I2V/Ref mode switcher inside panel
  supportsLipsync?: boolean        // Lipsync v3 — takes video + audio, no prompt
  startFrameLocksAspect?: boolean  // when a start frame is provided, aspect ratio is ignored by the model
  videoModes?: ("t2v" | "i2v" | "r2v" | "edit")[] // legacy per-model mode switcher (no longer used)
  supportsVideoExtend?: boolean // a video in the refs panel continues/edits it (Flux 3 extend, Omni edit)
  fpsOptions?: string[]         // LTX 2.5 exposes a frame-rate choice
  isVideoTool?: boolean         // transforms an uploaded clip (upscale/restore) — no prompt needed
  toolPrompt?: boolean          // this tool accepts an optional guidance prompt
  upscaleFactors?: string[]     // 1-4x, per the tool's own schema
  targetFpsOptions?: string[]   // frame interpolation targets
}

interface VideoItem {
  id: string
  dbId?: number           // DB GeneratedImage id — set on completion from status route
  videoUrl: string
  prompt: string
  model: string
  duration: string
  resolution?: string
  aspectRatio?: string
  createdAt: string
  failed?: boolean
  failError?: string
  queueRowId?: number   // server GenerationQueue row backing a failed tile
  failKey?: string      // dedupe key for optimistic vs server fails
  audioEnabled?: boolean
  startFrameUrl?: string
  endFrameUrl?: string
  motionVideoUrl?: string
  keepOriginalSound?: boolean
  characterOrientation?: "image" | "video"
}

interface VideoPendingSlot {
  slotId: string
  requestId: string
  falEndpoint: string
  prompt: string
  model: string
  duration: string
  resolution?: string
  ticketCost: number
  startedAt?: number
  aspectRatio?: string
  audioEnabled?: boolean
  startFrameUrl?: string
  endFrameUrl?: string
  motionVideoUrl?: string
  keepOriginalSound?: boolean
  characterOrientation?: "image" | "video"
  queueJobId?: number    // GenerationQueue DB ID — set when the job was queued (capacity exceeded)
}

interface VideoDetailData {
  id?: number             // DB GeneratedImage id for rating
  videoUrl: string
  prompt: string
  model: string
  duration?: string
  resolution?: string
  aspectRatio?: string
  createdAt?: string
  failed?: boolean
  failError?: string
  // Failed tiles: identity for the Dismiss action (VideoItem.id + server row link)
  failId?: string
  queueRowId?: number
  failKey?: string
  audioEnabled?: boolean
  startFrameUrl?: string
  endFrameUrl?: string
  motionVideoUrl?: string
  keepOriginalSound?: boolean
  characterOrientation?: "image" | "video"
}

